CATEGORY = "Перевозка"
PREFIX = "Перевозка "


def link_existing(apps, schema_editor):
    """Строки, созданные действием «расход рейса» («Перевозка <номер рейса>»), получают ссылку на
    рейс по номеру. Дубли (уже посчитанные дважды) остаются без ссылки: они блокируют повторное
    создание расхода и видны в списке строк заказа. Код приложения не импортируется."""
    from django.db import connection

    OrderService = apps.get_model("forwarding", "OrderService")
    Trip = apps.get_model("forwarding", "Trip")
    company_ids = sorted(
        set(
            OrderService.objects.filter(category=CATEGORY, title__startswith=PREFIX).values_list(
                "company_id", flat=True
            )
        )
    )
    for company_id in company_ids:
        with connection.cursor() as cursor:
            cursor.execute("SELECT set_config('app.company_id', %s, false)", [str(company_id)])
        trips = {t.number: t.pk for t in Trip.objects.filter(company_id=company_id)}
        taken = set()
        for line in OrderService.objects.filter(
            company_id=company_id, category=CATEGORY, title__startswith=PREFIX, trip__isnull=True
        ).order_by("id"):
            trip_id = trips.get(line.title[len(PREFIX) :])
            if trip_id is None or (line.order_id, trip_id) in taken:
                continue
            taken.add((line.order_id, trip_id))
            OrderService.objects.filter(pk=line.pk).update(trip_id=trip_id)
    with connection.cursor() as cursor:
        cursor.execute("SELECT set_config('app.company_id', '', false)")


